usage_example:
```hcl
resource "betterado_project" "example" {
  name               = "my-project"
  visibility         = "private"
  version_control    = "Git"
  work_item_template = "Agile"
}

resource "betterado_release_folder" "example" {
  project_id  = betterado_project.example.id
  path        = "\\MyFolder"
  description = "Folder for production release pipelines"
}
```
